insert into t_gen_field (name, title,dict_type,table_name, property_name
, ctype, type, column_type, comment, key_flag, identity_flag, remark, search_flag, edit_flag) VALUES

    (#{item.name},#{item.title},#{item.dictType},#{item.tableName},#{item.propertyName}
    ,#{item.ctype}, #{item.type},#{item.columnType},#{item.comment},#{item.keyFlag},#{item.identityFlag}
    ,#{item.remark}, #{item.searchFlag}, #{item.editFlag})
